export type IssueView = IssueView_Serialize | IssueView_Deserialize;

export type IssueView_Deserialize = {
	id: number,
	entry_idx: number,
	/**  Source path relative to the source's parent, lossily decoded. */
	path: string,
	rule: string,
	severity: IssueSeverity,
	message_key: string,
	before: number[],
	after: number[],
	before_text: string,
	after_text: string,
	decision: IssueDecision,
	custom_name?: string | null,
	/**  The decision was copied from the job this one repeats (Send again). */
	carried_over: boolean,
};

export type IssueView_Serialize = {
	id: number,
	entry_idx: number,
	/**  Source path relative to the source's parent, lossily decoded. */
	path: string,
	rule: string,
	severity: IssueSeverity,
	message_key: string,
	before: number[],
	after: number[],
	before_text: string,
	after_text: string,
	decision: IssueDecision,
	custom_name: string | null,
	/**  The decision was copied from the job this one repeats (Send again). */
	carried_over: boolean,
};

